      "keystrokes": "cat > wolfram_query.py << 'EOF'
#!/usr/bin/env python3
"""Wolfram|Alpha Query Script"""
import sys
import os
import requests
import xml.etree.ElementTree as ET

def query_wolfram_alpha(query, app_id):
    """Query the Wolfram|Alpha API and return results."""
    base_url = "https://www.wolframalpha.com/api/v1/simple-query"
    params = {
        'input': query,
        'appid': app_id,
        'format': 'plaintext'
    }

    try:
        response = requests.get(base_url, params=params, timeout=30)
        response.raise_for_status()
        return response.text
    except requests.RequestException as e:
        return f"Error: {e}"

def parse_wolfram_result(xml_response):
    """Parse Wolfram|Alpha XML response and extract results."""
    try:
        root = ET.fromstring(xml_response)
        results = []

        # Check for success
        success = root.find('success')
        if success is not None and success.text != 'true':
            return ["No result found"]

        # Extract pods (result sections)
        for pod in root.findall('.//pod'):
            title = pod.get('title', '')
            content = pod.find('subpod')
            if content is not None:
                plain_text = content.find('plaintext')
                if plain_text is not None and plain_text.text:
                    results.append(f"{title}: {plain_text.text}")

        return results
    except ET.ParseError:
        return [xml_response]

def main():
    if len(sys.argv) < 2:
        print("Usage: python3 wolfram_query.py <query>")
        print("Example: python3 wolfram_query.py 'integrate x^2 from 0 to 3'")
        sys.exit(1)

    query = ' '.join(sys.argv[1:])
    app_id = os.environ.get('WOLFRAM_APP_ID')

    if not app_id:
        print("Error: WOLFRAM_APP_ID environment variable is not set")
        sys.exit(1)

    print(f"Querying Wolfram|Alpha: {query}")
    result = query_wolfram_alpha(query, app_id)

    parsed_results = parse_wolfram_result(result)

    for line in parsed_results:
        print(line)

if __name__ == '__main__':
    main()
EOF
